async importAttachedSenderKey() {
  for (const info of Enigmail.msg.attachedSenderEmailKeysIndex) {
    await EnigmailKeyRing.importKeyDataWithConfirmation(
      window,
      [info.keyInfo],
      Enigmail.msg.attachedKeys[info.idx],
      true,
      ["0x" + info.keyInfo.fpr]
    );
  }
},
